def get_from_cache(db_name: str, cache_valid_seconds: int=0,
    skip_time_verification: bool=False) ->Optional[Dict[str, Any]]:
    try:
        if not os.path.exists(DB_CACHE_FILE):
            return None

        lock = FileLock(DB_CACHE_FILE + '.lock')
        with lock:
            with open(DB_CACHE_FILE, 'r') as f:
                cache = json.loads(f.read())

        if db_name not in cache:
            return None

        cached_data = cache[db_name]

        if not skip_time_verification and cache_valid_seconds:
            cached_time = cached_data.get('cached_at', 0)
            if time.time() - cached_time > cache_valid_seconds:
                return None

        return cached_data.get('data', None)
    except Exception as e:
        LOG.debug('Error reading from cache: %s', e)
        return None
```

