def write_to_cache(db_name: str, data: Dict[str, Any]) ->None:
    try:
        cache_dir = os.path.dirname(DB_CACHE_FILE)
        if cache_dir:
            os.makedirs(cache_dir, exist_ok=True)

        lock = FileLock(DB_CACHE_FILE + '.lock')
        with lock:
            cache = {}
            if os.path.exists(DB_CACHE_FILE):
                try:
                    with open(DB_CACHE_FILE, 'r') as f:
                        cache = json.loads(f.read())
                except Exception:
                    cache = {}

            cache[db_name] = {
                'cached_at': time.time(),
                'data': data
            }

            with open(DB_CACHE_FILE, 'w') as f:
                f.write(json.dumps(cache))
    except Exception as e:
        LOG.debug('Error writing to cache: %s', e)
